#include<bits/stdc++.h>using ll = long long;using namespace std; void solve() {    int n;    cin >> n;        vector<int> p(n + 1);    for (int i = 1; i <= n; i++) {        cin >> p[i];    }        vector<int> diff(n + 2, 0);    for (int i = 1; i <= n; i++) {        int L = i;        int R;                if (p[i] > i) {            R = p[i] - 1;        }                 else {            R = n;        }                diff[L]++;        diff[R + 1]--;    }        int max_chairs = 0;    int current_overlap = 0;        for (int i = 1; i <= n; i++) {        current_overlap += diff[i];        max_chairs = max(max_chairs, current_overlap);    }        cout << max_chairs << "\n";} int main() {    ios_base::sync_with_stdio(false);    cin.tie(NULL);        int t;    cin >> t;    while (t--) {        solve();    }        return 0;}